// Content with portions generated by generative AI platform
package org.eclipse.kura.internal.rest.auth.jwt;

import static org.eclipse.kura.internal.rest.auth.jwt.JwtRestServiceConstants.FAMILY_ID_CLAIM;
import static org.eclipse.kura.internal.rest.auth.jwt.JwtRestServiceConstants.GENERATION_CLAIM;

import java.util.Map;
import java.util.UUID;

import org.junit.Test;

import jakarta.ws.rs.core.Response.Status;

public class UntraceableRefreshTokenTest extends AbstractRefreshTokenFamilyScenario {

    private static final int UNAUTHORIZED = Status.UNAUTHORIZED.getStatusCode();

    private String loginFamilyId;
    private String refreshToken;

    @Test
    public void aRefreshTokenWithoutFamilyClaimsIsRefused() {
        givenAnExternalRefreshTokenWith(Map.of());

        whenTheRefreshTokenIsExchanged(this.refreshToken);

        thenTheExchangeStatusesAre(UNAUTHORIZED);
    }

    @Test
    public void aRefreshTokenOfAnUnknownFamilyIsRefused() {
        givenAnExternalRefreshTokenWith(Map.of(FAMILY_ID_CLAIM, UUID.randomUUID().toString(), GENERATION_CLAIM, 0L));

        whenTheRefreshTokenIsExchanged(this.refreshToken);

        thenTheExchangeStatusesAre(UNAUTHORIZED);
    }

    @Test
    public void aRefreshTokenWithAFractionalGenerationIsRefused() {
        givenALogin();
        givenAnExternalRefreshTokenWith(Map.of(FAMILY_ID_CLAIM, this.loginFamilyId, GENERATION_CLAIM, 0.5));

        whenTheRefreshTokenIsExchanged(this.refreshToken);

        thenTheExchangeStatusesAre(UNAUTHORIZED);
    }

    private void givenALogin() {
        this.loginFamilyId = (String) claimsOf(login().refreshToken()).get(FAMILY_ID_CLAIM);
    }

    private void givenAnExternalRefreshTokenWith(final Map<String, Object> claims) {
        this.refreshToken = externalRefreshTokenWith(claims);
    }

    private void whenTheRefreshTokenIsExchanged(final String token) {
        exchange(token);
    }
}
